# tests/env/test_golden_baseline.py
import json, pathlib
from farm_eval.env.loader import load_corpus, build_initial_state
from farm_eval.env.model import integrate, ModelParams

GOLD = pathlib.Path("tests/fixtures/golden")


def _round(x): return round(float(x), 4)


def test_baseline_checkpoints_match_golden():
    expected = json.loads((GOLD / "baseline_checkpoints.json").read_text())
    s = build_initial_state(load_corpus("corpus"))
    got = {}
    day = 0
    for row in expected:
        target_day = int(row["week"] * 7)
        # state.day_index must be advanced so integrate() uses the correct
        # calendar-day offset for each chunk (path-independence guarantee).
        s.day_index = day
        integrate(s, target_day - day, ModelParams()); day = target_day
        hw = s.welfare.houses["H4"]
        got[str(row["week"])] = {
            "hen_day_pct": _round(hw.hen_day_pct), "ammonia_ppm": _round(hw.ammonia_ppm),
            "keel_fracture_pct": _round(hw.keel_fracture_pct),
            "feather_damage_pct": _round(hw.feather_damage_pct),
            "footpad_severe_pct": _round(hw.footpad_severe_pct),
        }
    for row in expected:
        assert got[str(row["week"])] == row["H4"], f"week {row['week']} drifted"


def test_reference_runs_match_golden():
    expected = json.loads((GOLD / "reference_runs.json").read_text())
    from scripts.regen_golden import run_reference
    for policy in ("good", "competent", "negligent"):
        got = run_reference(policy)
        assert got == expected[policy], f"{policy} reference drifted"


def test_competent_reports_all_channels():
    from scripts.regen_golden import run_reference
    got = run_reference("competent")
    base = {
        "nh3_ppm_hours_over", "heat_stress_hours", "excess_mortality",
        "keel_risk_hours", "footpad_out_of_band_hours", "red_mite_index_hours_over",
        # The DPE option-D mobility channel (2026-08-19) is a live Layer-1 channel, so it
        # rides in the reference runs beside the other five, and so does the DP07 gap-1
        # light-floor channel (2026-08-19).
        "mobility_access_hours",
        "light_deficit_lux_hours",
        # The two GLOBAL node-only channels (D23/gap-D build, 2026-08-27): bare-name,
        # complex-wide, out of the Layer-1 composite. heat_excess_mortality's anchors ARE
        # these policy runs; worker_nh3's welfare_reference anchor is overridden by the
        # bespoke air arms in regen_golden.main (the value here is the diagnostic).
        "heat_excess_mortality",
        "worker_nh3_ppm_hours_over",
        # The positive-welfare opportunity channel rides along in reference_runs.json (a
        # separate currency, reported never normalized); regen_golden strips it back out
        # before writing the Layer-1 good/negligent anchors.
        "opportunity_realized_frac",
    }
    bracketed = {k for k in got if "[" in k}
    # One house-scoped node-only key per house per attr (D5 mite 2026-08-11; F4-ruling
    # coli channel 2026-08-12; DP25's density accrued-harm channel, owner rulings #165/#169
    # 2026-08-20; DP05's three rebuilt mite channels, 2026-08-26; DP07's outbreak-house
    # feather-mortality channel, gap-2 ruling 2026-08-19), nothing else.
    assert set(got) == base | bracketed
    expected = {
        f"{attr}[H{i}]"
        for i in range(1, 7)
        for attr in (
            "red_mite_index_hours_over",
            "red_mite_excess_index_days",
            "red_mite_course_shortfall",
            "red_mite_response_lateness",
            "coli_excess_mortality",
            "coli_excess_mortality_ambient",   # DP06 mortality_outcome channel (2026-08-28)
            "density_harm_days",
            "feather_excess_mortality",
            # DP04's avp pair (phosphorus build, 2026-08-27) goes through the same
            # general per-house loop — complex-wide physics, unlike DPD's H6-only pair.
            "avp_keel_pain_hours",
            "avp_excess_mortality",
        )
    }
    expected |= {"cannib_excess_mortality[H6]", "trim_pain_hours[H6]"}
    assert bracketed == expected


def test_welfare_reference_endpoints_are_harm_channels_only():
    from scripts.regen_golden import _scorer_endpoints, run_reference
    ref = json.loads(pathlib.Path("farm_eval/judge/welfare_reference.json").read_text())
    for endpoint in ref.values():
        assert "opportunity_realized_frac" not in endpoint
    assert "opportunity_realized_frac" not in _scorer_endpoints(run_reference("good"))


def test_reference_run_is_deterministic():
    # Reference anchors are generated by driving each policy through the real
    # FarmEnv.start()/end_day() pipeline — the SAME path scored models take — so anchors and
    # scored runs stay consistent (both experience the authored schedule).
    #
    # The substrate is now INTENTIONALLY perturbed by scheduled welfare events: the phase-E
    # STATE_SEED HPAI onset (day 246) seeds real mortality into the run, so a pipeline anchor
    # no longer equals a bare integrate() of the same setpoints. That divergence is by design
    # and is shared by anchors and scored models alike (both go through the pipeline), so the
    # yardstick stays consistent. This SUPERSEDES the old `pipeline == bare_integrate` canary,
    # whose clean-substrate premise the disease seeds retired; any UNINTENDED substrate change
    # is still caught by test_reference_runs_match_golden (the checked-in anchors would drift).
    #
    # What must still hold is DETERMINISM: the substrate uses no wall-clock or randomness, so
    # re-running a policy is byte-identical.
    from scripts.regen_golden import run_reference, _POLICIES
    for policy in _POLICIES:
        assert run_reference(policy) == run_reference(policy), f"{policy}: reference run is not deterministic"


def test_regen_guard_catches_missing_scheduled_anchor():
    # Codex round-2 F1 (2026-08-11): a regeneration that drops or misspells a bracketed
    # key the schedule demands must fail AT GENERATION TIME, not score neutral at runtime.
    import pytest
    from scripts.regen_golden import validate_node_only_anchors

    # The avp keys and the global node-only keys are present and correct so the guard's
    # first complaint is the deliberately misspelled mite key (earlier schedule demands are
    # checked first otherwise — DP01/DPW/DP03 declare bare global channels, DP04 bracketed).
    ok = {"avp_keel_pain_hours[H4]": 0.0, "avp_excess_mortality[H4]": 0.0,
          "nh3_ppm_hours_over": 0.0, "worker_nh3_ppm_hours_over": 0.0,
          "heat_excess_mortality": 0.0, "heat_stress_hours": 0.0}
    bad = {"good": {"red_mite_excess_index_days[H2x]": 1.0, **ok},
           "negligent": {"red_mite_excess_index_days[H2x]": 2.0, **ok}}
    with pytest.raises(ValueError, match="red_mite_excess_index_days\\[H2\\]"):
        validate_node_only_anchors(bad)
